function matchingBrace(text, open) {
  let depth = 0, quote = '', lineComment = false, blockComment = false;
  for (let i = open; i < text.length; i++) {
    const c = text[i], n = text[i + 1];
    if (lineComment) { if (c === '\\n') lineComment = false; continue; }
    if (blockComment) { if (c === '*' && n === '/') { blockComment = false; i++; } continue; }
    if (quote) {
      if (c === '\\\\') { i++; continue; }
      if (c === quote) quote = '';
      continue;
    }
    if (c === '/' && n === '/') { lineComment = true; i++; continue; }
    if (c === '/' && n === '*') { blockComment = true; i++; continue; }
    if (c === \"'\" || c === '\"' || c === '"'`'"') { quote = c; continue; }
    if (c === '{') depth++;
    if (c === '}') {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}
for (const file of files) {
  let source = fs.readFileSync(file, 'utf8');
  const edits = [];
  const re = /List\\((["'^'"\\n]*)\\)\\n([ \\t]*)\\.width\\((["'^'"\\n]*)\\)\\n\\2\\.height\\((["'^'"\\n]*)\\) \\{/g;
  let match;
  while ((match = re.exec(source))) {
    const open = match.index + match[0].lastIndexOf('{');
    const close = matchingBrace(source, open);
    if (close < 0) throw new Error('Unmatched List in ' + file);
    edits.push({
      start: match.index,
      end: match.index + match[0].length,
      replacement: 'List(' + match[1] + ') {',
      after: close + 1,
      suffix: '\\n' + match[2] + '.width(' + match[3] + ')\\n' + match[2] + '.height(' + match[4] + ')'
    });
  }
  for (let i = source.length - 1; i >= 0; i--) {
    const e = edits.find(x => x.after === i);
    if (e) source = source.slice(0, e.after) + e.suffix + source.slice(e.after);
  }
  for (const e of edits.slice().sort((a, b) => b.start - a.start)) {
    source = source.slice(0, e.start) + e.replacement + source.slice(e.end);
  }
  fs.writeFileSync(file, source);
}
